// === Tab: Lights ===
let colors = ["#233D4D", "#FE7F2D", "#FCCA46", "#A1C181", "#619B8A"];
let particles = [];
let amount = 40;

function setup() {
  createCanvas(300, 300);
  noStroke();
  frameRate(20);
  let p = new Particle(random(width), random(height), random(colors));
  particles.push(p);

	flex({ container: { padding: "20px" } })
}

function draw() {
  background("#282846");
  for (let i = 0; i < particles.length; i++) {
    if (particles[i].lv < 0) {particles.splice(i, 1);}
    particles[i].update();
    particles[i].show();
  }
  if (particles.length < amount) {
    var p = new Particle(random(width), random(height), random(colors));
    particles.push(p);
  }
}

// === Tab: particles ===
class Particle {
  constructor(x, y, clr) {
    this.posx = x;
    this.posy = y;
    this.size = random(10, 60);
    this.base = color("#000000");
    this.clr = color(clr);
    this.lv = 0;
    this.inc = 0.01;
    this.maxlv = random(0.4, 1);
  }
  update() {
    this.gradient = lerpColor(this.base, this.clr, this.lv);
    this.lv += this.inc;
    if (this.lv >= this.maxlv) {this.inc = -0.02;}
  }
  show() {
    push();
    blendMode(SCREEN);
    fill(this.gradient);
    drawingContext.shadowColor = color(this.gradient);
    drawingContext.shadowBlur = 30;
    circle(this.posx, this.posy, this.size);
    pop();
  }
}

